#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>

void print_stats(const char* name, const float* ptr, size_t n) {
    double sum = 0, sq_sum = 0;
    float min_val = ptr[0], max_val = ptr[0];
    for (size_t i = 0; i < n; i++) {
        float v = ptr[i];
        sum += v;
        sq_sum += v * v;
        if (v < min_val) min_val = v;
        if (v > max_val) max_val = v;
    }
    double mean = sum / n;
    double var = (sq_sum / n) - (mean * mean);
    printf("%-25s count=%-10zu mean=%8.4f std=%8.4f min=%8.4f max=%8.4f\n",
           name, n, mean, sqrt(var > 0 ? var : 0), min_val, max_val);
}

int main() {
    int fd = open("gpt2-124M.ckpt", O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
    struct stat st;
    fstat(fd, &st);
    size_t num_floats = st.st_size / sizeof(float);
    float* w = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (w == MAP_FAILED) { perror("mmap"); return 1; }
    printf("Mapped %zu floats\n", num_floats);

    // Test Layout 1: Karpathy / standard export order
    // wte (50257*768), wpe (1024*768),
    // then 12 blocks: ln_1.g(768), ln_1.b(768), attn.c_attn.w(768*2304), attn.c_attn.b(2304),
    // attn.c_proj.w(768*768), attn.c_proj.b(768), ln_2.g(768), ln_2.b(768),
    // mlp.c_fc.w(768*3072), mlp.c_fc.b(3072), mlp.c_proj.w(3072*768), mlp.c_proj.b(768)
    // finally ln_f.g(768), ln_f.b(768)

    size_t off = 0;
    print_stats("wte", w + off, 50257 * 768); off += 50257 * 768;
    print_stats("wpe", w + off, 1024 * 768); off += 1024 * 768;

    for (int l = 0; l < 12; l++) {
        char label[64];
        snprintf(label, sizeof(label), "L%d.ln_1.g", l);
        print_stats(label, w + off, 768); off += 768;
        snprintf(label, sizeof(label), "L%d.ln_1.b", l);
        print_stats(label, w + off, 768); off += 768;
        snprintf(label, sizeof(label), "L%d.attn_c_attn.w", l);
        print_stats(label, w + off, 768 * 2304); off += 768 * 2304;
        snprintf(label, sizeof(label), "L%d.attn_c_attn.b", l);
        print_stats(label, w + off, 2304); off += 2304;
        snprintf(label, sizeof(label), "L%d.attn_c_proj.w", l);
        print_stats(label, w + off, 768 * 768); off += 768 * 768;
        snprintf(label, sizeof(label), "L%d.attn_c_proj.b", l);
        print_stats(label, w + off, 768); off += 768;
        snprintf(label, sizeof(label), "L%d.ln_2.g", l);
        print_stats(label, w + off, 768); off += 768;
        snprintf(label, sizeof(label), "L%d.ln_2.b", l);
        print_stats(label, w + off, 768); off += 768;
        snprintf(label, sizeof(label), "L%d.mlp_c_fc.w", l);
        print_stats(label, w + off, 768 * 3072); off += 768 * 3072;
        snprintf(label, sizeof(label), "L%d.mlp_c_fc.b", l);
        print_stats(label, w + off, 3072); off += 3072;
        snprintf(label, sizeof(label), "L%d.mlp_c_proj.w", l);
        print_stats(label, w + off, 3072 * 768); off += 3072 * 768;
        snprintf(label, sizeof(label), "L%d.mlp_c_proj.b", l);
        print_stats(label, w + off, 768); off += 768;
    }
    print_stats("ln_f.g", w + off, 768); off += 768;
    print_stats("ln_f.b", w + off, 768); off += 768;
    printf("Total off=%zu, expected=%zu\n", off, num_floats);

    munmap(w, st.st_size);
    close(fd);
    return 0;
}
EOF
