#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <math.h>

int main() {
    int fd = open("gpt2-124M.ckpt", O_RDONLY);
    struct stat st;
    fstat(fd, &st);
    size_t num_floats = st.st_size / sizeof(float);
    float* w = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);

    for (size_t i = 0; i < num_floats - 768; i += 4) { // check every 4 floats
        double sum = 0;
        for (int k = 0; k < 768; k++) sum += w[i+k];
        double mean = sum / 768;
        if (mean > 0.7 && mean < 1.3) {
            double var = 0;
            for (int k = 0; k < 768; k++) {
                double d = w[i+k] - mean;
                var += d * d;
            }
            var /= 768;
            if (var < 0.2) {
                printf("Found candidate LN g at float offset %zu (%zu bytes): mean=%.3f, std=%.3f, first5=[%.2f, %.2f, %.2f, %.2f, %.2f]\n",
                       i, i*4, mean, sqrt(var), w[i], w[i+1], w[i+2], w[i+3], w[i+4]);
            }
        }
    }
    munmap(w, st.st_size);
    close(fd);
    return 0;
}
